// Generated by `bun scripts/hairline.ts` from hairline-figures/. Do not edit.
export default function define(HL, hairline) {
/**
 * DNA: a double helix of 20 base pairs lying side-on, its axis across the screen. Two
 * backbones wind round it with a major and a minor groove, and each rung is two
 * bases, the purine longer than its pyrimidine. The pointer's position along
 * the helix opens a bubble there: the backbones bulge apart and the base pairs
 * part, the nearer the wider, each on its own spring. At rest a small bubble is
 * already open, as if mid-transcription. The slider is the reach, in base pairs.
 *
 * Paint order is fixed by depth at rest; the bubble only moves parts outwards.
 */
const { Cam, clamp, fit, hull, open, poly, proj, spring, stepS, mk, pointer, register, disposer } = HL;

const NB = 20, RISE = 4.4, R0 = 13, BULGE = 7, TW = Math.PI / 5, OFF = (150 * Math.PI) / 180, TUBE = 1.2;
const SEQ = "ATGCGTACCGATTGCAGTCA", PAIR = { A: "T", T: "A", G: "C", C: "G" };
const VIEW = [0.612, 0.612, 0.5];
const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const X0 = (-(NB - 1) * RISE) / 2;

/** The share of the full opening at u reaches from the pointer: 1 → .31 at 42% → .09 beyond. */
const falloff = (u) =>
  u <= 0 ? 1 : u <= 0.417 ? 1 - (u / 0.417) * 0.6875 : u <= 1 ? 0.3125 - ((u - 0.417) / 0.583) * 0.2185 : 0.094;

/** The axis runs along U, across the screen; N (toward the viewer on the ground) and Z span the cross-section. */
const U = [Math.SQRT1_2, -Math.SQRT1_2, 0], N = [Math.SQRT1_2, Math.SQRT1_2, 0];
const at = (x, n, z) => [U[0] * x + N[0] * n, U[1] * x + N[1] * n, z];
/** Strand s at t base pairs along, at radius r: a world point. */
const strand = (s, t, r) => {
  const th = t * TW + s * OFF;
  return at(X0 + t * RISE, r * Math.cos(th), r * Math.sin(th));
};

/** An ellipsoid at c with orthogonal semi-axes a, b, n: the hull of its samples, as a path string. */
function egg(P, c, a, b, n) {
  const pts = [];
  for (let i = 0; i < 18; i++) for (let j = 0; j <= 6; j++) {
    const th = (i / 18) * Math.PI * 2, ph = (j / 6) * Math.PI, s = Math.sin(ph) * Math.cos(th), t = Math.sin(ph) * Math.sin(th), w = Math.cos(ph);
    pts.push(P(c[0] + a[0] * s + b[0] * t + n[0] * w, c[1] + a[1] * s + b[1] * t + n[1] * w, c[2] + a[2] * s + b[2] * t + n[2] * w));
  }
  return poly(hull(pts));
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.5);
  const ext = [];
  for (const x of [X0 - 2, -X0 + 2]) for (const [n, z] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) ext.push(at(x, n * (R0 + BULGE + 2), z * (R0 + BULGE + 2)));
  fit(C, ext, 200, 160);
  const P = proj(C), o0 = P(0, 0, 0), ox = P(...U)[0] - o0[0];
  let reach = value, px = null;

  // rest: a small bubble already open round base pair 15
  const pairs = [...SEQ].map((b, i) => ({ i, b, k: 0.55 * Math.exp(-(((i - 14) / 1.7) ** 2)) + 0.04 }));
  pairs.forEach((p) => (p.sp = spring(p.k, { eps: 0.002 })));
  /** The radius of the helix t base pairs along, between the springs of the pairs either side. */
  const rad = (t) => {
    const i = clamp(Math.floor(t), 0, NB - 1), j = clamp(i + 1, 0, NB - 1), f = clamp(t - i, 0, 1);
    return R0 + BULGE * (pairs[i].sp.x * (1 - f) + pairs[j].sp.x * f);
  };

  // parts: a backbone piece per strand per pair, and two bases per pair, sorted far to near at rest
  const parts = [];
  for (let i = 0; i < NB; i++) for (const s of [0, 1]) {
    parts.push({ kind: "bone", i, s, depth: dot(strand(s, i, R0), VIEW) });
    parts.push({ kind: "base", i, s, depth: dot(strand(s, i, R0 * 0.5), VIEW) });
  }
  parts.sort((a, b) => a.depth - b.depth);
  const g = mk("g", {}, svg);
  for (const q of parts) {
    q.sil = mk("path", { class: q.kind === "bone" ? "sil" : "" }, g);
    if (q.kind === "bone") q.cr = mk("path", { class: "nf lo" }, g);
  }
  const bases = (i) => parts.filter((q) => q.kind === "base" && q.i === i);

  /** A backbone piece: a tube from half a pair before to half a pair after, as a ribbon on screen, and its centre line. */
  function bone(q) {
    const pts = [];
    for (let k = 0; k <= 6; k++) {
      const t = clamp(q.i - 0.55 + (k / 6) * 1.1, -0.3, NB - 0.7);
      pts.push(P(...strand(q.s, t, rad(t))));
    }
    const side = (sg) => pts.map((p, k) => {
      const a = pts[Math.max(0, k - 1)], b = pts[Math.min(6, k + 1)], dx = b[0] - a[0], dy = b[1] - a[1], l = Math.hypot(dx, dy) || 1;
      return [p[0] - (dy / l) * TUBE * C.S * sg, p[1] + (dx / l) * TUBE * C.S * sg];
    });
    q.sil.setAttribute("d", poly([...side(1), ...side(-1).reverse()]));
    q.cr.setAttribute("d", open(pts));
  }

  /** A base: a rounded bar from its backbone toward its partner's, a purine longer than a pyrimidine. */
  function base(q) {
    const r = rad(q.i), from = strand(q.s, q.i, r), to = strand(1 - q.s, q.i, r);
    const chord = 2 * R0 * Math.sin(OFF / 2), v = [to[0] - from[0], to[1] - from[1], to[2] - from[2]], l = Math.hypot(...v);
    const letter = q.s ? PAIR[SEQ[q.i]] : SEQ[q.i], half = (chord * ("AG".includes(letter) ? 0.55 : 0.38) - TUBE) / 2;
    const d = v.map((x) => x / l), c = from.map((x, k) => x + d[k] * (half + TUBE));
    // the base's width lies across the chord in the cross-section: d × U
    const w = [d[1] * U[2] - d[2] * U[1], d[2] * U[0] - d[0] * U[2], d[0] * U[1] - d[1] * U[0]];
    q.sil.setAttribute("d", egg(P, c, d.map((x) => x * half), U.map((x) => x * 1.5), w.map((x) => x * 1.2)));
  }

  let drawn = "";
  const B = register(stage, (dt) => {
    let m = false;
    for (const p of pairs) if (stepS(p.sp, dt)) m = true;
    const key = pairs.map((p) => p.sp.x.toFixed(4)).join();
    if (key !== drawn) { drawn = key; for (const q of parts) (q.kind === "bone" ? bone : base)(q); }
    return m;
  });
  bag.add(B.unregister);

  const lead = pairs.reduce((a, b) => (b.k > a.k ? b : a));
  function retarget() {
    const pick = px === null ? lead : pairs[clamp(Math.round((px - X0) / RISE), 0, NB - 1)];
    for (const p of pairs) p.sp.t = px === null ? p.k : falloff(Math.abs(X0 + p.i * RISE - px) / (reach * RISE));
    for (const p of pairs) for (const q of bases(p.i)) q.sil.classList.toggle("hi", p === pick);
    read.textContent = px === null ? "rest" : `bp ${String(pick.i + 1).padStart(2, "0")} ${pick.b}·${PAIR[pick.b]}`;
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => { px = clamp((p[0] - o0[0]) / ox, X0 - RISE, -X0 + RISE); retarget(); },
    leave: () => { px = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();

  return {
    set: (v) => { reach = v; if (px !== null) retarget(); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "dna",
  means: "A double helix: the pointer opens a bubble where it is, the backbones bulge apart and the base pairs part.",
  rules: [1, 3, 5, 6],
  range: [1.5, 3, 5.5],
  mount,
});
}
